mapper.sql:
WHERE l.publish_status = 'PUBLISHED' AND u.occupancy_status = 'VACANT'

    AND l.district = #{query.district}


    AND (l.title LIKE concat('%', #{query.keyword}, '%') OR l.community_name LIKE concat('%', #{query.keyword}, '%') OR l.address LIKE concat('%', #{query.keyword}, '%'))


    AND l.rent_cent >= #{query.minRentCent}


    AND l.rent_cent <= #{query.maxRentCent}


    AND u.room_count = #{query.rooms}
